function nidAlphabet(preset){
  preset=preset||'url';
  if(preset==='hex') return '0123456789abcdef';
  if(preset==='upper') return 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  if(preset==='no-look') return '23456789abcdefghjkmnpqrstuvwxyz';
  return 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_~';
}
function nidRng(){
  if(typeof window!=='undefined' && window.crypto && window.crypto.getRandomValues){
    var a=new Uint32Array(1); return function(){ window.crypto.getRandomValues(a); return a[0]/4294967296; };
  }
  return Math.random;
}
function nidGenerate(size, alphabet, rnd){
  if(!rnd) rnd=nidRng();
  if(size<1||size>128) return { error:'长度需在 1–128' };
  var s=''; for(var i=0;i<size;i++) s+=alphabet.charAt(Math.floor(rnd()*alphabet.length));
  return { error:null, id:s };
}
function nidUuid(){
  if(typeof window!=='undefined' && window.crypto && window.crypto.randomUUID) return window.crypto.randomUUID();
  var hex='0123456789abcdef', r=nidRng(), s='';
  for(var i=0;i<32;i++){ if(i===8||i===12||i===16||i===20) s+='-'; s+=hex.charAt(Math.floor(r()*16)); }
  return s;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { nidAlphabet:nidAlphabet, nidGenerate:nidGenerate, nidUuid:nidUuid, nidRng:nidRng };
}
if (typeof window !== 'undefined') {
  window.NanoidForgePure = { nidAlphabet:nidAlphabet, nidGenerate:nidGenerate, nidUuid:nidUuid, nidRng:nidRng };
}
